// ==UserScript==
// @name         三合一通用主控脚本
// @namespace    http://tampermonkey.net/
// @version      1.0.0
// @description  合并 m.main.js, p.main.js, t.main.js 自动释放加载
// @run-at       document-end
// @match        *://*/*
// @grant        GM_download
// @grant        GM_setClipboard
// @grant        GM_xmlhttpRequest
// @grant        unsafeWindow
// ==/UserScript==

(function() {
    'use strict';

    // 标准 Unicode Base64 解码
    function b64ToUtf8(str) {
        const binary = atob(str);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) {
            bytes[i] = binary.charCodeAt(i);
        }
        return new TextDecoder('utf-8').decode(bytes);
    }

    const scripts = [{"name": "m.main.js", "b64": ""}, {"name": "p.main.js", "b64": ""}, {"name": "t.main.js", "b64": ""}];

    scripts.forEach(item => {
        try {
            const rawCode = b64ToUtf8(item.b64);
            
            // 在独立沙盒闭包内释放并注入 GM API
            const runner = new Function(
                'GM', 
                'GM_info', 
                'unsafeWindow', 
                'GM_download', 
                'GM_setClipboard', 
                'GM_xmlhttpRequest', 
                `
                try {
                    ${rawCode}
                } catch(err) {
                    console.error('[Bundle Loader] 脚本 [' + item.name + '] 运行时异常:', err);
                }
                `
            );

            runner(
                typeof GM !== 'undefined' ? GM : {}, 
                typeof GM_info !== 'undefined' ? GM_info : {}, 
                typeof unsafeWindow !== 'undefined' ? unsafeWindow : window,
                typeof GM_download !== 'undefined' ? GM_download : undefined,
                typeof GM_setClipboard !== 'undefined' ? GM_setClipboard : undefined,
                typeof GM_xmlhttpRequest !== 'undefined' ? GM_xmlhttpRequest : undefined
            );
            
            console.log('[Bundle Loader] 已载入并释放脚本: ' + item.name);
        } catch(e) {
            console.error('[Bundle Loader] 解析脚本 [' + item.name + '] 失败:', e);
        }
    });
})();
